__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"POLITIQUE",{enumerable:!0,get:function(){return t}});const t=[{type:"h1",texte:"Politique de confidentialit\xe9 de Sakia"},{type:"p",texte:"Derni\xe8re mise \xe0 jour : 19 novembre 2026."},{type:"p",texte:"Sakia relie ton entra\xeenement et ton alimentation : la s\xe9ance du jour ajuste tes cibles du jour. Pour cela, l\u2019application traite des donn\xe9es qui touchent \xe0 ta sant\xe9. Cette page explique lesquelles, pourquoi, o\xf9 elles vont et comment les reprendre ou les effacer."},{type:"h2",texte:"Qui est responsable"},{type:"p",texte:"Sakia est un projet \xe9tudiant men\xe9 dans le cadre de l\u2019\xc9cole Centrale de Lille. Responsable du traitement : Anisse Benallegue, \xe9tudiant \xe0 l\u2019\xc9cole Centrale de Lille, Cit\xe9 Scientifique, CS20048, 59651 Villeneuve d\u2019Ascq Cedex. Contact pour toute question sur tes donn\xe9es : sakia.fitness@gmail.com."},{type:"h2",texte:"Sans compte, rien ne quitte ton t\xe9l\xe9phone"},{type:"p",texte:"Tu peux utiliser Sakia sans cr\xe9er de compte. Ton profil, ton plan, tes s\xe9ances, tes repas et tes pes\xe9es sont alors enregistr\xe9s uniquement sur ton t\xe9l\xe9phone. La recherche d\u2019aliments courants se fait dans la table Ciqual de l\u2019Anses, incluse dans l\u2019application : elle ne transmet rien. Une seule exception : quand tu scannes un code-barres ou que tu cherches un produit de marque, Sakia interroge la base publique Open Food Facts en ne lui transmettant que le code du produit ou les mots cherch\xe9s."},{type:"h2",texte:"Les donn\xe9es trait\xe9es avec un compte"},{type:"li",texte:"Compte : ton adresse e-mail et ton mot de passe, chiffr\xe9 par le service d\u2019authentification. Sakia ne conna\xeet jamais ton mot de passe en clair."},{type:"li",texte:"Profil : sexe biologique, date de naissance, taille, objectif, exp\xe9rience, et la fourchette de calories que tu suis d\xe9j\xe0 si tu l\u2019indiques."},{type:"li",texte:"Suivi : ton plan d\u2019entra\xeenement, tes s\xe9ances et leurs s\xe9ries (charges, r\xe9p\xe9titions, ressenti), tes repas (nom, calories, macronutriments, provenance de la saisie), tes pes\xe9es, les g\xeanes que tu signales, les jours o\xf9 tu annules une s\xe9ance, et les pas de charge que tu corriges."},{type:"li",texte:"Groupes de constance, si tu en rejoins : le nom du groupe, ton pseudo et la date \xe0 laquelle tu l\u2019as rejoint."},{type:"p",texte:"Poids, alimentation, performances et g\xeanes signal\xe9es sont des donn\xe9es de sant\xe9 au sens de l\u2019article 9 du RGPD. Sakia ne les enregistre sur ses serveurs qu\u2019avec ton consentement explicite, donn\xe9 \xe0 la cr\xe9ation du compte."},{type:"p",texte:"Sakia ne collecte ni ta localisation, ni tes contacts, ni d\u2019identifiant publicitaire. Il n\u2019y a ni publicit\xe9 ni traceur publicitaire dans l\u2019application."},{type:"h2",texte:"Aucune intelligence artificielle externe"},{type:"p",texte:"Sakia n\u2019envoie aucune donn\xe9e \xe0 un service d\u2019intelligence artificielle. Tes cibles, ta progression et les ajustements de la semaine sont calcul\xe9s par l\u2019application elle-m\xeame, avec des r\xe8gles v\xe9rifiables."},{type:"h2",texte:"Groupes de constance"},{type:"p",texte:"Un groupe de constance est facultatif. En le rejoignant, tu acceptes que ses membres voient ton pseudo, les jours et l\u2019heure de fin de tes s\xe9ances \xe0 partir du jour o\xf9 tu le rejoins, et ton nombre de s\xe9ances pr\xe9vues par semaine. Ils ne voient jamais tes charges, ton poids, tes repas, tes g\xeanes, ton adresse e-mail ni ton identifiant de compte. Quand tu quittes le groupe, ils ne voient plus rien de toi."},{type:"h2",texte:"Rappels et partage"},{type:"li",texte:"Les rappels de s\xe9ance sont programm\xe9s sur ton t\xe9l\xe9phone : rien n\u2019est envoy\xe9 pour les d\xe9clencher."},{type:"li",texte:"La carte de s\xe9ance que tu partages est une image cr\xe9\xe9e sur ton t\xe9l\xe9phone. Elle ne contient ni ton poids, ni tes repas, ni les g\xeanes signal\xe9es ; c\u2019est toi qui choisis o\xf9 l\u2019envoyer."},{type:"h2",texte:"Pourquoi ces donn\xe9es sont trait\xe9es"},{type:"li",texte:"Fournir le service : calculer tes cibles, piloter ta progression, sauvegarder et synchroniser ton suivi. Base l\xe9gale : l\u2019ex\xe9cution du service que tu as demand\xe9 (article 6.1.b du RGPD) et ton consentement explicite pour les donn\xe9es de sant\xe9 (article 9.2.a)."},{type:"li",texte:"Montrer ta constance aux membres d\u2019un groupe que tu as rejoint. Base l\xe9gale : ton consentement, donn\xe9 en rejoignant le groupe et retir\xe9 en le quittant (articles 6.1.a et 9.2.a)."},{type:"p",texte:"Tes donn\xe9es ne sont ni vendues ni utilis\xe9es \xe0 des fins publicitaires."},{type:"h2",texte:"O\xf9 vont tes donn\xe9es"},{type:"li",texte:"Supabase : h\xe9bergement de la base de donn\xe9es et de l\u2019authentification, dans l\u2019Union europ\xe9enne (Irlande)."},{type:"li",texte:"Open Food Facts : uniquement le code-barres scann\xe9 ou les mots cherch\xe9s, jamais ton identit\xe9 ni ton journal."},{type:"h2",texte:"Combien de temps"},{type:"p",texte:"Tes donn\xe9es sont conserv\xe9es tant que ton compte existe. Quand tu supprimes ton compte, il est effac\xe9 imm\xe9diatement de la base, avec tout ton suivi. Un \xe9l\xe9ment que tu supprimes dans l\u2019application est marqu\xe9 comme supprim\xe9 pour que tes autres appareils l\u2019apprennent, puis effac\xe9 d\xe9finitivement sous 90 jours. L\u2019h\xe9bergeur conserve des copies de sauvegarde selon les conditions de son offre : une donn\xe9e supprim\xe9e peut y subsister jusqu\u2019\xe0 l\u2019expiration de ces copies."},{type:"h2",texte:"Tes droits"},{type:"li",texte:"Acc\xe9der \xe0 tes donn\xe9es et les emporter : Profil, puis Compte et donn\xe9es, puis \xab Exporter mes donn\xe9es \xbb (fichier JSON)."},{type:"li",texte:"Les corriger : directement dans l\u2019application."},{type:"li",texte:"Les effacer et retirer ton consentement : Profil, puis Compte et donn\xe9es, puis \xab Supprimer mon compte \xbb. La suppression est d\xe9finitive."},{type:"li",texte:"Tu peux aussi demander la limitation d\u2019un traitement ou t\u2019y opposer, en \xe9crivant \xe0 l\u2019adresse de contact ci-dessus."},{type:"li",texte:"Si tu estimes que tes droits ne sont pas respect\xe9s, tu peux adresser une r\xe9clamation \xe0 la CNIL (cnil.fr)."},{type:"h2",texte:"S\xe9curit\xe9"},{type:"p",texte:"Les \xe9changes avec les serveurs sont chiffr\xe9s (HTTPS). Chaque utilisateur ne peut lire et \xe9crire que ses propres donn\xe9es, garanti par des r\xe8gles appliqu\xe9es dans la base elle-m\xeame. La session est conserv\xe9e dans le trousseau s\xe9curis\xe9 du t\xe9l\xe9phone."},{type:"h2",texte:"\xc2ge minimum"},{type:"p",texte:"Sakia est r\xe9serv\xe9e aux personnes majeures."},{type:"h2",texte:"Sant\xe9"},{type:"p",texte:"Les cibles et recommandations de Sakia sont des estimations issues d\u2019\xe9quations de population et de tes saisies. Elles ne remplacent pas l\u2019avis d\u2019un m\xe9decin ou d\u2019un di\xe9t\xe9ticien. Si une g\xeane persiste plusieurs jours, consulte un professionnel de sant\xe9."},{type:"h2",texte:"Modifications"},{type:"p",texte:"Toute modification de cette politique sera dat\xe9e en haut de cette page et signal\xe9e dans l\u2019application si elle change la fa\xe7on dont tes donn\xe9es sont trait\xe9es."}]},908,[]);